# This dylib is built with -Z dylib-lto which internalizes the whole crate
# into consumers; the only dynamic export is the rustc metadata blob that
# downstream crates (e.g. base/request download_server) read via --extern.
# Lock the surface to exactly that.

{
  global:
    rust_metadata*;
  local:
    *;
};
